def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 3:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_def = 0
    my_def = 0
    for m in opp:
        if m == 'D':
            opp_def += 1
    for m in me:
        if m == 'D':
            my_def += 1

    # Always defect against an always-defecting opponent
    if n >= 10:
        recent_opp_def = sum(1 for m in opp[-10:] if m == 'D')
        if recent_opp_def == 10:
            return 'D'

    # Compute retaliation count: opponent defected immediately after our defection
    retaliations = 0
    for i in range(n - 1):
        if me[i] == 'D' and opp[i + 1] == 'D':
            retaliations += 1

    # Endgame logic
    if n >= 99:
        return 'D'
    if my_def > 0 and retaliations == 0 and n >= 97:
        return 'D'

    last_opp = opp[-1]
    last_my = me[-1]

    # If opponent defected last round:
    if last_opp == 'D':
        # If we also defected, break the cycle by cooperating
        if last_my == 'D':
            return 'C'
        # If we cooperated and they defected, check if they defected twice in a row
        if n >= 2 and opp[-2] == 'D':
            return 'D'
        else:
            return 'C'
    else:
        # Opponent cooperated last round. Cooperate by default.
        return 'C'
